const msTotal=msDomains.reduce((n,d)=>n+d[2].length,0);
function msSourceCard(ch){const entries=msRefs.filter(x=>x[2].includes(ch[0]));return detail('Microsoft official source library · '+entries.length+' contextual references',entries.map(r=>'<div class="un-word"><b>'+H(r[0])+'</b> — '+H(r[3])+'<p>'+A('https://github.com/'+r[1],'GitHub repository')+' · '+A(r[4],'Official learning reference')+'</p></div>').join('')+P('Original academy explanations and simulations are not Microsoft lab reproductions. Individual files, terms and versions must be reviewed before copying.'));}
function msSkillCard(ch){let entries=msDomains.flatMap((d,i)=>d[2].map((a,j)=>[d[0],i+1,j+1,...a])).filter(x=>x[3]===ch[0]);return detail('Official SC-300 objective crosswalk · '+entries.length+' items',P('Mapped to the October 28, 2026 objectives. The full instruction is now embedded in the relevant teaching unit above. Use this index to return directly to any skill. Exercises linked below model only supported subsets.')+entries.map(x=>'<div class="un-word"><b>'+H('D'+x[1]+'.'+x[2]+' · '+x[4])+'</b>'+' <button class="btn" data-action="ms-depth-open" data-id="D'+x[1]+'.'+x[2]+'">Open complete skill lesson</button>'+P(x[5])+(x[6]?B(x[6],'Open related practice'):'<p class="small muted">Guided reference / real-tenant verification outstanding.</p>')+'</div>').join('')+'<p>'+A(msGuide,'Official complete skills measured')+'</p>');}
function msLabCard(ch){let rows=msLabs.map((a,i)=>[i,...a]).filter(x=>x[1]===ch[0]);return detail('Microsoft lab alignment · '+rows.length+' published entries',P('All lab numbers correspond to the official index. The academy links to the official instructions and supplies original contextual practice; a link is not a reproduction of every step.')+rows.map(a=>'<div class="un-word"><b>SC-300 lab '+String(a[0]).padStart(2,'0')+' · '+H(a[2])+'</b><p>'+A(directLab(a[0]),'Open exact official lab instructions')+'</p>'+(a[0]===0?P(a[3]):B(a[3],'Related fictional exercise (partial model)'))+'</div>').join('')+P('Real labs may need licensed tenants, privileged accounts, VMs or Azure resources. Do not start paid trials or resources without explicit approval.'));}
function msSection(ch){return sec('Microsoft-aligned learning and practical work',P('Study these resources after the chapter teaching, then use the practice to establish evidence. The course remains one sequence.')+msSkillCard(ch)+msLabCard(ch)+msSourceCard(ch)+msSims.filter(x=>x[1]===ch[0]).map(x=>B('course/lab/'+x[0],x[2])).join('')+(['computer','network','ad','users','ops'].includes(ch[0])?B('course/lab/commands','Read-only command practice'):''));}
function msCoverage(){return layout(B('course/home','← Course home')+'<h1>SC-300 objective-by-objective crosswalk</h1>'+P(msTotal+' distinct skill targets, mapped to the existing chapters. Microsoft guide dated October 28, 2026. The guide shows 25–30% authentication/access in its at-a-glance summary but 20–25% in that section heading; use Microsoft’s current exam page rather than treating either number as an exact blueprint.')+msDomains.map((d,i)=>sec(d[0]+' · '+d[2].length+' skill targets',d[2].map((a,j)=>'<div class="un-word"><b>D'+(i+1)+'.'+(j+1)+' · '+H(a[1])+'</b>'+P(a[2])+'<button class="btn" data-action="ms-depth-open" data-id="D'+(i+1)+'.'+(j+1)+'">Open full skill lesson</button>'+B('course/chapter/'+a[0],'Study '+chapter(a[0])[1])+(a[3]?B(a[3],'Related partial practice'):'<p class="small muted">Real configuration or additional simulator work outstanding.</p>')+'</div>').join(''))).join('')+'<p>'+A(msGuide,'Official exam guide')+'</p>'+P('Mapped does not mean every operation has a high-fidelity simulation or that the learner is exam-ready. Use authorized real labs for full configuration.'));
}
function msGet(id){return msSims.find(x=>x[0]===id);}
function msState(l){return s.ms.sim[l[0]]||{values:{},runs:0,last:null};}
function msEvaluate(l,values){return l[5].map(t=>({name:t[0],pass:t[1].every(k=>{const f=l[4].find(f=>f[0]===k);return Number(values[k]??0)===f[3]}),why:t[2]}));}
function msSim(id){const l=msGet(id);if(!l)return layout('<h1>Exercise not found</h1>'+B('course/practice','Practice and assessments'));const m=msState(l);return layout(B('course/chapter/'+l[1],'← Return to chapter')+'<h1>'+H(l[2])+'</h1>'+P(l[3])+P('Local fictional state only. Select configuration, run validation, introduce the fault and run again. This is a simplified teaching model, not a full implementation of Microsoft services.')+l[4].map(f=>sec(f[1],f[2].map((x,i)=>'<button class="btn '+(Number(m.values[f[0]]??0)===i?'primary':'')+'" data-action="ms-config" data-id="'+H(id)+'" data-key="'+H(f[0])+'" data-value="'+i+'">'+H(x)+'</button>').join(''))).join('')+sec('Validate configured state','<button class="btn primary" data-action="ms-run" data-id="'+H(id)+'">Run verification</button><button class="btn" data-action="ms-reset" data-id="'+H(id)+'">Reset fictional configuration</button>'+P('Runs: '+m.runs)+(m.last?m.last.map(x=>'<div class="un-result"><b>'+H((x.pass?'PASS · ':'FAIL · ')+x.name)+'</b>'+P(x.why)+'</div>').join(''):P('No current results. Configuration changes invalidate the previous results.'))+P('Fault injection assignment: '+l[6])));}
