const cmdTasks=[
["ps-help","PowerShell","Discover commands","Get-Command Get-MgUser","Get-Command discovers a command and reports metadata; it does not execute the requested command.",()=>[{CommandType:'Function',Name:'Get-MgUser',Source:'Microsoft.Graph.Users (fictional)'}]],
["ps-users","PowerShell","List fixture users","Get-MgUser -All","-All asks the Graph PowerShell cmdlet to retrieve all pages, given authorization.",()=>commandUsers],
["ps-filter","PowerShell","Filter Finance users","Get-MgUser -All | Where-Object Department -eq 'Finance'","The pipeline sends objects; Where-Object tests their Department property. The fixture assumes Department was returned; real Graph requests may require -Property Department.",()=>commandUsers.filter(x=>x.Department==='Finance')],
["ps-disabled","PowerShell","List disabled identities","Get-MgUser -All | Where-Object AccountEnabled -eq $false","Boolean $false is distinct from the string 'false'. Real Graph retrieval may need explicit selected properties.",()=>commandUsers.filter(x=>!x.AccountEnabled)],
["ps-select","PowerShell","Project names and enabled state","Get-MgUser -All | Select-Object DisplayName,AccountEnabled","Select-Object returns named properties rather than a new access grant.",()=>commandUsers.map(({DisplayName,AccountEnabled})=>({DisplayName,AccountEnabled}))],
["graph-user","Graph","Read one fixture object","GET /v1.0/users/U1?$select=id,displayName,accountEnabled","A GET reads data; $select controls returned fields; real requests need a valid Graph token and permissions. U1 is fictional.",()=>({id:'U1',displayName:'Alex Morgan',accountEnabled:true})],
["graph-page","Graph","Read first paged result","GET /v1.0/users?$top=2","A real nextLink is an opaque URL to follow as returned. The following URL is a fictional stand-in and must not be used against Graph.",()=>({value:commandUsers.slice(0,2),'@odata.nextLink':'https://graph.example/v1.0/users?cursor=fixture-page2'})],
["graph-next","Graph","Follow the fixture nextLink","GET https://graph.example/v1.0/users?cursor=fixture-page2","Follow the returned nextLink unchanged in real use; it can include opaque tokens. This URL is not a real service.",()=>({value:commandUsers.slice(2)})],
["kql-failed","KQL","Find failed sign-ins","SigninLogs | where ResultType != '0'","where filters rows. In this fixture ResultType '0' is success; verify actual schema.",()=>commandLogs.filter(x=>x.ResultType!=='0')],
["kql-project","KQL","Project failed sign-in identity and app","SigninLogs | where ResultType != '0' | project UserPrincipalName, AppDisplayName","project chooses columns; where removes rows.",()=>commandLogs.filter(x=>x.ResultType!=='0').map(({UserPrincipalName,AppDisplayName})=>({UserPrincipalName,AppDisplayName}))],
["kql-count","KQL","Count events per user","SigninLogs | summarize Count=count() by UserPrincipalName","summarize aggregates by the specified field; this counts all events, not unique people.",()=>[...new Set(commandLogs.map(x=>x.UserPrincipalName))].map(UserPrincipalName=>({UserPrincipalName,Count:commandLogs.filter(x=>x.UserPrincipalName===UserPrincipalName).length}))],
["kql-failcount","KQL","Count failures per user","SigninLogs | where ResultType != '0' | summarize Count=count() by UserPrincipalName","Filter before aggregation to count only failed fixture events.",()=>[...new Set(commandLogs.filter(x=>x.ResultType!=='0').map(x=>x.UserPrincipalName))].map(UserPrincipalName=>({UserPrincipalName,Count:commandLogs.filter(x=>x.UserPrincipalName===UserPrincipalName&&x.ResultType!=='0').length}))]
];
function cmdNorm(s){return String(s).trim().replace(/\s+/g,' ').toLowerCase();}
function cmdRun(task,raw){const t=cmdTasks.find(t=>t[0]===task);if(!t||cmdNorm(raw)!==cmdNorm(t[3]))return {ok:false,output:'Not a supported exact exercise command. Review the syntax and try again. This restricted simulator executes no shell or network code.'};return {ok:true,output:JSON.stringify(t[5](),null,2),why:t[4]};}
function msCommandPage(){return layout(B('course/practice','← Practice and assessments')+'<h1>PowerShell, Graph and KQL laboratory</h1>'+P('Read-only simulated command exercises using fixed fictional data. This is a restricted command matcher, not PowerShell, Microsoft Graph or a real KQL engine. Type the example syntax; see its evaluated fixture output and explanation. No network or command execution.')+cmdTasks.map(t=>{let saved=s.ms.commands[t[0]];return sec(t[1]+' · '+t[2],'<p><code>'+H(t[3])+'</code></p><form id="ms-cmd" data-id="'+H(t[0])+'"><textarea name="command" aria-label="Command">'+H(saved?.input||'')+'</textarea><button type="submit" class="btn primary">Run fictional command</button></form>'+(saved?'<div class="un-result"><b>'+H(saved.result.ok?'Supported syntax · fixture output':'Try again')+'</b><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+H(saved.result.output)+'</pre>'+P(saved.result.why||'')+'</div>':'')+P(t[4]));}).join(''));}
function msExamScore(e){return msExam.reduce((n,q,i)=>n+Number(e.answers[i]===q[3]),0);}
function msExamPage(){let e=s.ms.exam,answered=msExam.filter((q,i)=>Number.isInteger(e.answers[i])).length;return layout(B('course/practice','← Practice and assessments')+'<h1>Independent SC-300 practice · 24 original scenarios</h1>'+P('Six scenarios per domain, intentionally equal-sized for diagnostic breadth, not a replica of Microsoft’s exam weighting. No feedback before submission. Do not use course notes for the first attempt.')+P(answered+' of '+msExam.length+' answered')+(e.submitted?sec('Results',P('Score: '+msExamScore(e)+' / '+msExam.length+'; first submitted score: '+e.first+'/'+msExam.length+'.')+msDomains.map((d,i)=>P(d[0]+': '+msExam.reduce((n,q,j)=>n+Number(q[0]===i&&e.answers[j]===q[3]),0)+'/6')).join('')+'<button class="btn" data-action="ms-exam-reset">Retry same set</button>'+P('Retaking the same items is recall practice, not a fresh independent test.')):'')+msExam.map((q,i)=>sec('Scenario '+(i+1),P(q[1])+q[2].map((x,j)=>'<button class="btn '+(e.answers[i]===j?'primary':'')+'" data-action="ms-exam-pick" data-id="'+i+'" data-value="'+j+'" '+(e.submitted?'disabled':'')+'>'+H(x)+'</button>').join('')+(e.submitted?'<div class="un-result">'+H(e.answers[i]===q[3]?'Correct':'Review: '+q[2][q[3]])+P(q[4])+'</div>':''))).join('')+(e.submitted?'':'<button class="btn primary" data-action="ms-exam-submit" '+(answered===msExam.length?'':'disabled')+'>Submit all 24 answers</button>'));}
function msPracticeHub(){return sec('Official Microsoft-aligned practice',B('course/coverage','SC-300 objective crosswalk')+B('course/lab/commands','PowerShell, Graph and KQL')+B('course/assessment','Independent 24-scenario assessment')+msSims.map(x=>B('course/lab/'+x[0],x[2])).join('')+P('No additional paid services or cloud resources are used by these local exercises.'));}
function msAudit(){let checks=[],ck=(name,pass)=>checks.push({name,pass:!!pass});ck('98 distinct objective targets',msTotal===98);ck('all objective chapters exist',msDomains.every(d=>d[2].every(x=>!!chapter(x[0]))));ck('all 29 SC-300 lab entries mapped',msLabs.length===29&&msLabs.every(x=>chapter(x[0])));ck('15 source repositories',msRefs.length===15);ck('coverage rendered',msCoverage().includes('98 distinct skill targets'));for(const l of msSims){let good=Object.fromEntries(l[4].map(x=>[x[0],x[3]]));ck(l[0]+' positive validation',msEvaluate(l,good).every(t=>t.pass));ck(l[0]+' default not passed',msEvaluate(l,{}).some(t=>!t.pass));for(const f of l[4]){let v={...good,[f[0]]:0};ck(l[0]+' fault '+f[0],msEvaluate(l,v).some(t=>!t.pass));}ck(l[0]+' rendered',msSim(l[0]).includes('Run verification'));}for(const t of cmdTasks){ck(t[0]+' fixture command',cmdRun(t[0],t[3]).ok);ck(t[0]+' arbitrary command rejected',!cmdRun(t[0],'Remove-Item C:\\').ok);}ck('KQL filter matches fixture',JSON.parse(cmdRun('kql-failed',cmdTasks.find(x=>x[0]==='kql-failed')[3]).output).length===2);ck('PowerShell filter matches fixture',JSON.parse(cmdRun('ps-disabled',cmdTasks.find(x=>x[0]==='ps-disabled')[3]).output)[0].Id==='U3');ck('24 distinct assessment questions',msExam.length===24&&new Set(msExam.map(q=>q[1])).size===24&&msDomains.every((d,i)=>msExam.filter(q=>q[0]===i).length===6));ck('assessment scoring',msExamScore({answers:Object.fromEntries(msExam.map((q,i)=>[i,q[3]]))})===24);ck('commands rendered',msCommandPage().includes('restricted command matcher'));ck('assessment rendered',msExamPage().includes('24 original scenarios'));return checks;}


/* Objective-by-objective original teaching content, authored from the current study guide and reviewed lab references. */
const depthData=[[[2,1,"A directory role definition is a named collection of permitted directory actions. A role assignment binds that definition to a principal and supported scope. Built-in roles have Microsoft-defined permissions; custom roles use supported resource actions, subject to licensing. Neither is Azure resource RBAC.","Entra ID > Roles and administrators: inspect Application Administrator versus a narrowly scoped custom app role. In a fictional request, principal U1 needs only approved application operations. Examine role permissions, select supported scope, assign, and record assignment ID and status. Avoid Global Administrator.","Sign in as U1 in a separate authorized test session; perform the intended operation and test an unrelated privileged operation. If unexpectedly allowed, inspect additional direct/group/active roles.","An app support employee only needs one supported directory action. Which design minimizes exposure?","Choose a built-in least-privileged role or custom role with the required action and supported scope.","Grant Global Administrator and rely on training.","Use an Azure subscription Reader role."],[2,1,"An administrative unit (AU) is a management scope over selected directory objects, not an independent tenant or a permission grant. Use it when geographically or organizationally delegated administrators need supported administration of only specified objects.","Design AU-Houston with users Alex and Casey, and AU-Dallas with Morgan. Assign a supported User Administrator or Helpdesk role at Houston scope, subject to limitations on privileged users and supported actions. Document what tenant-wide permissions remain.","Compare an allowed Houston action to a denied Dallas action; inspect role scope and membership if both succeed. AU membership by itself does not grant resource access.","A regional team must reset eligible users' passwords only in Houston. What boundary belongs in the design?","Administrative unit scope plus an appropriate supported role.","A Microsoft 365 license for every Houston user.","A second domain name with no scoped role."],[2,1,"AU membership and role assignment are two separate records. A standard AU groups users/groups/devices; supported dynamic membership and restricted management AUs have distinct behavior and licensing. Choose only the features required.","Entra ID > Administrative units: create Houston Support; add approved objects; inspect its ID; add an eligible supported scoped administrator through Roles and administrators. If a dynamic rule is used, validate the resulting membership, not just the rule.","Read back membership, principal, role definition and directory scope. Test a supported action inside scope. If an object is missing, inspect membership evaluation; if access is broad, inspect other assignments.","An administrator was added as an AU member but has no delegated authority. What is missing?","An appropriate scoped administrative role assignment.","A new UPN suffix.","A device compliance policy."],[2,1,"Effective permissions combine applicable role assignments and supported scopes. An eligible PIM assignment is not active authority; inherited role-assignable group membership and other active roles may grant additional actions.","For U1, list direct role assignments, role-assignable groups and active PIM assignments. Example: Houston-scoped Helpdesk Administrator plus tenant-wide User Administrator. Determine the permission and scope of each action independently.","Use a separate test identity and allowed/denied operations. An unexpectedly allowed Dallas operation can come from a separate tenant-wide role; do not assume the narrow AU overrides it.","Why can U1 still manage Dallas users after receiving a Houston-scoped role?","An additional active or inherited assignment may grant tenant-wide access.","All AU roles always overwrite previous roles.","A verified domain grants administration."],[1,2,"A custom domain proves control over a DNS namespace so supported Microsoft services can use it. Verification does not automatically change existing UPNs, SMTP addresses or mail routing. A UPN is a login name, an SMTP address is for mail.","Entra ID > Domain names: add contoso.example, obtain the exact generated TXT or supported verification record, publish only in approved DNS, verify, then plan UPN suffix updates and application claims. In Microsoft 365, inspect required service records separately; MX routes mail.","Verify domain status and test a pilot user's login, mail and SSO after approved changes. If verification fails, check public authoritative DNS and exact token. Do not alter mail records merely to fix identity verification.","The new custom domain is verified. Does that prove Exchange mail is routed to Microsoft 365?","No; verify the separate Exchange service/MX configuration.","Yes, verification replaces all MX records.","Yes, if the user belongs to an AU."],[0,2,"Company branding customizes supported sign-in experiences; it is not identity proof. Default and localized branding may include logos, background, sign-in text and supported layout settings. Branding depends on feature/license and sign-in flow.","Entra ID > Company branding: choose an approved default logo, accessible colors, concise support text and language-specific variants where supported. Example: en-US and es-US sign-in text. Preview before publishing; do not expose sensitive internal contact data.","Test normal and localized login in a private session; verify official sign-in URL and authentication still works. If a logo does not show, inspect selected language, sign-in flow, image constraints and caching.","A branded login page looks like Contoso. Is appearance proof that it is legitimate?","No; validate the actual domain and authentication flow.","Yes, matching colors prove trust.","Yes, branding is equivalent to MFA."],[0,2,"Tenant properties describe organization metadata. User settings govern defaults such as allowed app registrations; group settings govern supported group creation/ownership behaviors; device settings govern join/registration limits and allowed populations. Defaults are distinct from per-object assignments.","Inventory current settings before changes. Example: tenant T1, app registrations restricted, approved group creators, device join allowed to pilot group. Use the appropriate Entra properties/settings pages, change one approved setting in isolation, keep rollback values.","Test a standard pilot user before and after, and verify admin operations still work. If an action still succeeds, inspect privileges and settings applying to that object; document exceptions.","A non-admin can create an app even after a policy change. What should be examined?","Effective app-registration settings and the user's actual roles/permissions.","Their display name.","The tenant's logo size."],[0,1,"A user object holds account identity, UPN, stable object ID, type, enabled status and descriptive properties. Creating it does not automatically assign app access. A synchronized user's authoritative attributes may need to be edited at the source.","Create fictional Alex with UPN alex@contoso.example, display name Alex Morgan, accountEnabled true, department Helpdesk, usageLocation US. Review generated ID U1, then assign only approved groups/licensing. Disable instead of prematurely deleting during offboarding; authorized deleted-user recovery is time limited.","Read user ID, attributes and effective access; verify new sign-in and an unauthorized resource. If updates revert, check source of authority/sync. After approved removal, validate actual denial and retention obligations.","Alex's UPN changes. Which field is generally the durable identifier for the same directory object?","Object ID.","Display name.","Department."],[1,3,"A security group collects principals for access; a Microsoft 365 group also supports collaboration resources. Membership may be assigned or dynamic. A dynamic rule evaluates user/device attributes; group membership and downstream authorization are separate.","Create fictional Finance Readers as security group. Assigned member Casey; alternatively use a supported dynamic rule such as user.department -eq \"Finance\". Verify group type, membership type, owner, actual membership and app assignment; use role-assignable groups only where explicitly appropriate.","After Alex transfers, inspect evaluated membership and any direct grants, then test Finance and Helpdesk access. Delay or rule error can make actual membership differ from expected. Nested/group behavior varies by feature.","A dynamic rule was saved but Casey has not appeared in the group yet. What establishes entitlement?","Actual evaluated membership plus the resource assignment and access result.","The rule text alone.","The tenant subscription ID."],[0,null,"Custom security attributes are governed key/value metadata for Entra objects and supported authorization scenarios. They are separate from ordinary profile attributes; role permissions to define and assign them are deliberately separated.","Define attribute set BusinessClassification, attribute CostCenter (string, allowed values FIN/IT); use appropriate attribute definition and assignment roles at the supported scope. Assign IT to approved fictional principal. Do not store passwords or unnecessary sensitive data.","Read back value using an appropriately authorized identity; test an unauthorized reader/writer. If an administrator cannot see the values, review attribute-specific role and set scope, not merely User Administrator.","A User Administrator cannot assign a governed custom security attribute. What should be examined?","Attribute assignment role and attribute-set scope.","Add every employee as Global Administrator.","Change the UPN to the attribute name."],[1,1,"Bulk operations transform many records from an approved input set. CSV has headers and rows; PowerShell emits objects through a pipeline. A preview identifies invalid UPNs, duplicate IDs and missing required fields before any write.","Download the current bulk template rather than inventing headers. In a fictional CSV, check Alex, Casey, Sam records for unique sign-in names. Preview Import-Csv, inspect Get-MgContext, read matching users with Get-MgUser -All -Property Id,UserPrincipalName; use the authorized Graph cmdlet only after approval.","Inspect per-row failures, compare intended IDs to actual records, and record rollback for successful writes. Do not run broad write commands against a live tenant just to learn.","Five rows failed and five succeeded. What should a safe retry do?","Inspect individual errors and retry only corrected failed rows after checking current state.","Blindly rerun every write.","Suppress the error output."],[0,10,"A cloud device object represents a device identity. Registered, Entra joined and hybrid joined are different relationships. Windows flags and cloud DeviceId connect endpoint evidence to a directory object; enrollment is a separate management relationship.","On approved Windows client inspect dsregcmd /status. Example: DomainJoined YES, AzureAdJoined YES = hybrid joined in this context; DeviceId D1 matches Entra Devices. Compare a registered BYOD record, cloud joined record and hybrid joined record. Check status, owner, enabled and stale records.","Check matching device ID and join state in sign-in details. If a device is duplicated, investigate the actual signed-in device and enrollment before deleting any record. Join alone does not prove compliant.","DomainJoined=YES and AzureAdJoined=YES. Which relationship is indicated?","Microsoft Entra hybrid join, subject to matching device evidence.","Intune compliance by definition.","Entra registered BYOD only."],[0,3,"A product SKU contains service plans. A user can receive direct or group-based product licensing; usage location and available seats/service plan conflicts affect assignment. A license enables a feature, not private resource authorization.","In authorized Microsoft 365 admin center inspect Billing > Licenses. Example: Helpdesk group gets approved SKU, user Alex usageLocation US, selected plans enabled. Compare direct and inherited assignment sources; do not buy seats or activate trials. Review available existing entitlements.","Inspect license assignment errors and assigned plans, then test relevant workload. Removing a group license might leave a direct assignment. Missing usage location or exhausted seats needs correction, not a broader role.","An employee is in a licensed group but has a licensing error. What evidence is relevant?","Usage location, available seats, service-plan conflicts and assignment error.","The SAML NameID alone.","The Azure VM's managed identity."],[2,4,"External collaboration settings regulate who may invite guests, guest visibility of directory objects and supported domain restrictions. They do not replace cross-tenant access or resource permissions.","External Identities > External collaboration settings: design approved inviter roles, limited guest visibility and supported domain allow/deny rule. Example: authorized sponsors may invite partner.example; unapproved domain is denied. Evaluate email OTP/self-service only where required.","Test approved inviter/domain and unauthorized inviter/domain. Inspect guest directory visibility and resource entitlement separately. Settings can affect business collaboration; record rollback before changing.","A guest invitation is allowed. Does that mean the guest may open all SharePoint documents?","No; resource assignments and sharing/access policy remain separate.","Yes, guest invitation is full resource consent.","Only if their UPN includes #EXT#."],[2,5,"Invitation creates or refers to a local external user representation and delivers a redemption path. Invitation state indicates whether the guest has accepted; it does not guarantee access to a specific app. Bulk invitations use the current CSV template.","Create a fictional invitation for casey@partner.example with approved redirect, sponsor and message; add only approved project assignment after identity validation. For bulk, validate email addresses, duplicate entries and per-row errors against current template.","Check external user object, invitation/redemption status, assigned resources and actual sign-in. If guest cannot redeem, inspect identity provider, invite address, cross-tenant policy and invitation state before reinviting.","A guest has PendingAcceptance state. What is not yet demonstrated?","Successful redemption and target resource access.","Existence of any invitation record.","The tenant's verified domain."],[2,24,"An external user may persist after a project ends; guest lifecycle includes sponsor, access assignment, review, expiry, disable/delete according to approved retention policy. B2B user type alone does not identify every access path.","Inspect external user U-G1: home identity, sponsor, groups, enterprise app roles, packages and direct resource grants. After contract expiry, remove approved access, revoke sessions/disable or delete per policy; avoid removing unrelated collaboration that remains authorized.","Verify access denied at actual project resource and review alternate direct/group grants. Check guest account state, sign-in evidence and data retention, not just package expiration.","The guest's package expired but direct project membership remains. What should be done?","Review and remove approved obsolete direct and inherited access paths.","Assume expiry removed all permissions.","Reset home tenant administrator password."],[2,null,"Cross-tenant access settings control B2B collaboration/direct connect inbound and outbound relationships. Inbound concerns external identities accessing your resources; outbound concerns your identities accessing another organization. Supported trust settings can accept external MFA or device claims.","External Identities > Cross-tenant access settings: inspect default and organization-specific settings for Partner T2. Plan inbound pilot users/apps and outbound access; enable trust of MFA/compliant/hybrid claims only with approved trust assessment. Distinguish B2B direct connect and collaboration.","Validate an allowed and denied inbound case, and an outbound case. Inspect sign-in details, home/resource tenant IDs and trust settings; check resource permissions separately.","Contoso users must access Partner resources. Which Contoso direction applies?","Outbound access from Contoso, alongside Partner inbound policy.","Contoso inbound only.","Microsoft 365 license assignment only."],[2,null,"Cross-tenant synchronization provisions supported B2B users from source to target with mappings and scope; it is not a merger of directories or a replacement for cross-tenant sign-in policies. Target users have tenant-local object IDs.","Design Source T1 > Target T2 with approved inbound synchronization setup and supported automatic redemption settings. Configure scoped source assignments and attribute mappings, test on-demand provisioning for Alex, then monitor create/update/deprovision and provisioning logs.","Verify source U1 maps to target U9; check role/entitlement in target independently. If no target record, inspect source scope, target permission, mapping and provisioning errors; if sign-in denied inspect cross-tenant and resource access.","Synchronization created U9 in Target T2. Does that prove Alex can read target Payroll?","No; target authorization and applicable access policy must be satisfied.","Yes, synchronized identities are tenant admins.","Yes, source object ID automatically grants access."],[3,6,"External federation lets a supported external identity provider authenticate a user through a trust relationship. SAML or WS-Fed conveys signed assertions/tokens under configured issuer, endpoints and certificate trust; local guest/resource access still applies.","External Identities > identity providers: identify partner domain, protocol, issuer/entity ID, passive sign-in endpoint and signing certificate/metadata. Configure only supported verified domain/trust arrangement in authorized lab; invite a scoped test user and check claim mapping.","Validate successful redemption, issuer/signature and a permitted resource. Expired certificate, wrong issuer or mismatched claim can break federation even when directory records exist. Use approved certificate rollover and fallback procedure.","Partner changes signing certificate and federated logins fail. What is the first relevant trust check?","Configured issuer, metadata/signing certificate and actual assertion validation.","Group license seat count.","Intune encryption policy."],[0,7,"Connect Sync uses a synchronization engine with connectors for source and target, import, synchronization rules/metaverse and export. The source anchor links corresponding identities. Scope and mapping determine which attributes are exported.","In a disposable approved AD/Entra lab, choose supported Connect version, inventory domains and verified UPN suffixes, scope pilot OU, choose source anchor and authentication method. Review import/sync/export result and staging-mode plan; never install on production for practice.","Compare source AD record, connector-space/metaverse evidence where applicable and cloud object. If export fails, investigate duplicate attributes, unverified suffix or permission; if import missing, inspect source scope and replica.","An AD user exists but connector import never sees it. Which evidence comes first?","Source replica and connector scope/import results.","Cloud app consent.","A PIM activation request."],[0,null,"Cloud Sync uses a cloud-managed provisioning configuration and lightweight on-premises agents. It differs from Connect Sync in supported objects, topology, features and administration; check current feature matrix before selecting.","Plan agent placement and redundancy, register approved agents in a training environment, create scoped configuration, define mapping and test a selected user using supported on-demand provisioning. Avoid overlapping conflicting sync scopes.","Inspect agent health, provisioning logs, source scope and target object. If the agent is healthy but target record absent, check scope/mapping and specific provisioning event rather than reinstalling blindly.","An agent is healthy but a user outside the selected scope never appears in Entra. What is likely?","Scope exclusion, not proof of an agent outage.","App registration consent failure.","Missing Conditional Access session frequency."],[1,7,"Password hash synchronization (PHS) synchronizes a further-derived representation of the AD password hash; cloud validation does not require a live on-premises controller for each new cloud password sign-in. It does not copy plaintext passwords and is distinct from object synchronization.","Select supported PHS configuration in approved hybrid lab, ensure pilot user is synchronized and password changes flow, then test a cloud sign-in. Compare object sync status with password sync evidence; do not attempt to extract actual hashes.","If user object exists but new password fails, inspect password sync health, freshness and account state plus policy. PHS cloud validation can continue during an on-prem outage when other cloud controls pass.","Does PHS require a PTA agent to validate every cloud password sign-in?","No; current synchronized derived hash enables cloud validation.","Yes, PTA is mandatory.","Yes, OAuth requires an on-prem password."],[1,null,"Pass-through authentication (PTA) forwards a protected validation request through an available on-premises agent to AD. The agent validates credentials against AD; cloud policy then applies. Agent health and AD connectivity are key dependencies.","Choose PTA for approved requirements, deploy supported agents with redundancy, confirm Entra configuration and agent status, test pilot cloud login and approved failure/recovery behavior. PHS may be configured separately as a planned recovery option, not automatic failover by default.","Inspect agent availability and on-prem AD validation errors plus sign-in details. If all agents are unavailable, new PTA password validation may fail. Test a supported recovery strategy rather than relying on assumptions.","All PTA agents are unavailable. What does a working cloud user object prove?","The object exists, but new PTA password validation may still fail.","The password is always cloud-validated.","All sign-in policies are bypassed."],[1,null,"Seamless SSO is an optional experience using Kerberos for eligible domain-connected browsers under supported PHS/PTA deployments. It reduces prompts; it is not PHS, PTA or the Primary Refresh Token (PRT).","In approved lab confirm supported client, corporate network/domain connectivity, service principal/AD computer account configuration and browser zone settings per current docs. Test domain user navigating to a supported Microsoft sign-in without unnecessary prompts.","If password sign-in works but seamless SSO does not, inspect client domain connectivity, Kerberos ticket and browser configuration. Modern Entra joined devices may use PRT-based SSO instead.","A domain-connected user can authenticate with PHS but sees a prompt. Which is a plausible separate issue?","Seamless SSO Kerberos/browser path.","PHS must have deleted the object.","A license automatically prevents prompts."],[1,null,"AD FS federation delegates authentication to an external federation service. Moving toward managed authentication changes trust and validation dependencies; apps, claims, MFA and recovery must be assessed before changing domains.","Inventory federated domains, apps relying on AD FS claims and authentication rules; select managed authentication method; establish cloud emergency access; use supported staged rollout for eligible pilot users; validate business apps and document rollback before converting approved domains.","Inspect sign-in method, token claims and app compatibility; monitor old/new paths and failures. Do not retire federation infrastructure until approved migration and dependencies are verified.","What must precede conversion of a production federated domain?","Pilot validation, claims/application dependency inventory and recovery/rollback plan.","Deleting every federated app.","Assigning all users Global Administrator."],[2,null,"Connect Health provides supported health monitoring for hybrid identity components. An alert identifies a monitored condition; it is evidence, not proof that it caused every user's failure.","Review supported Connect Health views/agents for the relevant sync, AD DS or AD FS deployment; inspect agent last contact, service health and specific alert. Correlate timestamps with import/export or sign-in failure; validate licensing and supported agent.","After approved remediation, confirm health signal returns and original operation succeeds. If health is green but export still fails, inspect detailed provisioning evidence; do not treat dashboard color as end-to-end validation.","Connect Health alert is cleared but Alex still fails synchronization. What is next?","Investigate the specific sync import/export and source object evidence.","Close ticket because alert cleared.","Disable directory audits."]],[[2,8,"Authentication planning matches proof methods to threat, population, device and recovery needs. Authentication strength limits acceptable combinations; method availability is not the same as a requirement. Recovery and emergency access are independent design decisions.","Define workforce, admins, contractors and recovery groups. Example: administrators use phishing-resistant methods; supported pilot workforce uses Authenticator/passkey; approved bootstrap TAP. Inventory registration and licenses, rollout in pilot, document recovery and excluded emergency identities.","Test allowed proof, disallowed weak proof, onboarding/recovery and approved break-glass procedure. Check authentication details and CA result, not only method registration.","Which design proves admins must use phishing-resistant proof?","A supported authentication-strength requirement targeted to admins, with approved methods and validated sign-ins.","Only enable Authenticator for everyone.","Only add users to an app group."],[2,8,"Authenticator may provide push/number matching and supported passwordless flows. Passkeys use FIDO public-key challenge response and origin binding. TAP is a time-limited bootstrap/recovery credential. Certificate-based authentication validates approved X.509 certificate trust and mapping. These are different proof mechanisms.","In Authentication methods policy target pilot groups per method; configure supported passkey/authenticator options, TAP issuance lifetime and use restrictions, and CBA trusted issuer/binding settings where authorized. Have test identities register supported methods and compare sign-in proof.","Inspect method registration and authentication details; test allowed strength and disallowed method. Do not publish TAPs, private keys, certificates with secrets or passwords. Method availability alone does not enforce MFA.","What property makes a passkey phishing resistant in its supported flow?","Challenge signing and binding to the legitimate service origin.","Sending the private key to the web server.","Reusing a six-digit static password."],[2,8,"Tenant-wide MFA behavior can involve security defaults, legacy per-user settings, and Conditional Access; authentication methods policy controls availability. Avoid conflicting or redundant configuration and do not disable existing security controls without approved replacement.","Inventory current methods, security defaults/per-user MFA status and CA policies. For modern supported design, target pilot group and app with CA MFA or authentication strength, exclude approved emergency recovery accounts as appropriate, use report-only before enforcement.","Check actual authentication details and all matching policy results. Existing registration is not proof of enforced prompt; existing session proof can satisfy requirements depending on context. Validate approved recovery path.","A method is enabled tenant-wide. Does every sign-in necessarily require that method?","No; method eligibility and access-policy enforcement are separate.","Yes, enabled methods always force MFA.","Yes, provided a custom domain exists."],[2,9,"Self-service password reset (SSPR) lets eligible users recover passwords using configured verification methods. For synchronized users, supported password writeback can update the on-premises authority; it depends on configuration, permissions and licensing.","Entra password reset settings: select approved pilot group, supported recovery methods/count, registration and notification settings. Where needed plan writeback via supported hybrid configuration. Register test user and perform approved recovery in separate session.","Verify user can authenticate with updated password at intended systems; inspect reset and writeback events. If cloud reset succeeds but AD does not update, check writeback support/agent permissions and source policy.","A hybrid user's cloud recovery must change the on-premises password. What feature needs explicit configuration?","Supported password writeback.","A new app role.","A My Apps collection."],[2,null,"Windows Hello for Business uses asymmetric keys bound to supported user/device enrollment; PIN or biometric unlocks use of the local key rather than sending the PIN to the service. Trust model and provisioning prerequisites depend on cloud/hybrid design.","Plan cloud Kerberos trust or another supported trust model as appropriate, verify device join and management, configure approved WHfB policy (often through Intune), ensure prerequisite MFA and enrollment, provision pilot and test sign-in/resource scenarios.","Inspect dsregcmd /status and relevant provisioning/sign-in logs; confirm expected key/SSO behavior and recovery. A local PIN failure is different from a remote password failure.","Does a Hello PIN normally travel to Entra as the shared cloud password?","No; it authorizes local use of a device-bound credential.","Yes, it is the user's UPN.","Yes, it is a SAML assertion."],[2,null,"Disabling account blocks new authentication as supported; revoking sign-in sessions invalidates supported refresh/session artifacts. Existing access tokens may remain usable until expiry or supported CAE reevaluation. Resource grants and retention are separate.","For approved leaver, identify source authority, disable account (on-prem if synchronized as required), synchronize, use supported revoke sessions operation, remove obsolete entitlements and deprovision targets. Record exact user ID and approval; avoid deleting retained data automatically.","Verify denied new sign-in and resource outcomes, inspect sign-in and audit logs and supported token/session behavior. Existing resource sessions may require additional service-specific action.","Why is disabling an account not the same as immediate universal termination of all existing sessions?","Token lifetime, CAE/client/resource support and service-specific session handling differ.","Disabling a user only changes their display name.","All sessions are controlled by DNS."],[2,12,"Entra password protection rejects weak/banned passwords using Microsoft global banned terms and supported custom lists. Smart lockout limits repeated failed authentication behavior; it is not the same as password complexity. On-prem protection requires supported agents/configuration.","Plan custom banned terms reflecting organizational risks, choose approved enforcement or audit approach for on-prem extension, review smart-lockout configuration and AD lockout interaction. Test a fictional banned password in authorized isolated lab only; never probe live accounts repeatedly.","Review password change/reset or agent logs, and distinguish banned-password rejection from lockout. Avoid weakening thresholds to bypass an incident; inspect source policy.","Which feature prevents selection of an organization-specific weak password?","Custom banned-password protection, not merely smart-lockout duration.","App collection.","A service principal display name."],[1,null,"Microsoft Entra Kerberos provides supported Kerberos authentication for particular hybrid/resource scenarios, such as cloud Kerberos trust or supported Azure Files configurations. It is not a universal replacement for traditional domain controllers or PHS.","Choose a supported scenario and read its current prerequisites. In a training design identify AD domain, Entra Kerberos server object/trust, client and resource, permitted identities and resource permissions. For WHfB cloud trust, validate relevant hybrid user and DC reachability as required.","Inspect relevant ticket evidence with approved tools and test actual resource access separately. If a Kerberos ticket exists but file access denied, inspect share/data ACL; if ticket missing, check trust and client prerequisites.","A user obtains a supported Kerberos ticket but cannot read a share. What remains?","Resource-level permissions and applicable access rules.","Convert all groups to Microsoft 365 groups.","Disable token validation."],[0,13,"Conditional Access evaluates targeted identities, resources and conditions against grant and session controls. Design starts with a business rule, threat and measurable intended behavior; policies can combine and block takes precedence over grants.","Write requirement: Finance pilot, Payroll app, require approved phishing-resistant authentication and compliant device; specify exclusions and emergency recovery, report-only evaluation, rollback owner and success/denial tests. Map subject, resource, condition, control and state before creating.","Review What If plus actual sign-in logs and report-only results. Verify allowed and denied scenarios with no unexpected broad impact. Only authorized rollout moves to On.","What is the safest first deployment of a new broad access requirement?","Scoped report-only pilot, evidence review and approved enforcement.","Immediately turn On for all users.","Disable all existing controls."],[0,13,"Assignments determine where a CA policy applies: users/groups or supported workload identities, target resources/actions and selected conditions. Exclusions remove scope for that policy only; another policy may still apply.","Create fictional CA-Finance-Pilot, include FinancePilot, target Payroll, inspect device/client/location conditions, exclude only justified emergency identities. Test Alex in group and Morgan outside. Workload policies have different supported controls.","In What If and sign-in logs inspect Applied/Not applied and reason. If policy does not apply, check group membership, target resource and conditions. A successful sign-in does not by itself prove exclusion.","Alex is not in FinancePilot and no other matching scope exists. What should this pilot policy do?","Not apply to Alex.","Grant Finance app permission automatically.","Always block the entire tenant."],[0,13,"Grant controls decide whether access is blocked or requires supported proof, such as MFA, strength or compliant device. Multiple controls can require all or one selected control; every applicable enforced policy must be satisfied.","Model CA-Finance with MFA AND compliant device. Alex MFA=true/compliant=false fails this grant; change to OR and it may meet that policy's grant, but other policies/resource authorization still matter. Do not change AND to OR just to hide compliance failures.","Run both combinations in simulator, inspect policy and individual control outcomes; test enforced block and report-only separately. If unexpectedly allowed, check policy state, scope and other conditions.","MFA passes, compliant device fails, enforced rule requires both. Expected outcome?","The grant requirements are not satisfied.","MFA overrides every device requirement.","App assignment automatically meets the grant."],[0,13,"What If predicts applicability for selected inputs; report-only provides observed evaluation without enforcing that policy; sign-in logs show actual event details and policy outcomes. None replaces testing a real approved operation.","Choose test user, app, client and device; evaluate What If; perform test sign-in in authorized pilot; inspect Conditional Access tab, correlation ID, auth details and device. Compare policy IDs and results with expected scope/control.","A mismatch requires checking actual resource, device signals, group evaluation and existing proof. Confirm original permitted action and denied case before enforcement. Record rollback and review report-only results over representative use.","What If predicts grant, but actual sign-in is blocked. What evidence is most useful?","Actual sign-in event, matching policies, conditions and device/authentication details.","Policy display color.","The tenant logo."],[2,null,"Session controls constrain supported post-authentication behavior. Sign-in frequency defines when reauthentication is required under applicable behavior; persistent browser session controls cookie/session persistence. App-enforced restrictions and CA App Control are different supported mechanisms.","Define business requirement for sensitive browser sessions. Scope test policy to approved group/app, choose supported frequency/persistence setting, and check interaction with client/session behavior. Avoid claiming every refresh triggers new MFA.","Test fresh browser, existing session, elapsed interval and applicable resource/client; inspect actual reauthentication and policy details. Do not infer universal token expiry from a sign-in-frequency setting.","What does sign-in frequency govern?","Reauthentication behavior under supported session policy, not app assignment.","The number of licenses assigned.","DNS TTL for the tenant."],[1,null,"Device-based access can use device identity and posture, while application-enforced restrictions pass relevant context to supported resources that enforce limited access. A managed/compliant device is distinct from registered or hybrid-joined device.","Plan supported unmanaged-browser access to SharePoint or Exchange with appropriate workload settings and CA session control, or require compliant device for full access. Compare allowed limited action and blocked download in approved lab; check Intune compliance for intended devices.","Inspect matching device ID, join/compliance signals, policy session result and resource-side behavior. If restriction not enforced, confirm client/resource support and workload configuration.","A device is joined but lacks compliance. Does join alone satisfy Require compliant device?","No; the relevant compliance signal must satisfy the grant.","Yes, join and compliance are synonyms.","Yes, if user has an E5 license."],[2,null,"Continuous Access Evaluation (CAE) allows supported resource/client combinations to react to certain critical events and location-policy changes without waiting for conventional token expiry. It does not guarantee every service instantly ends every session.","Map supported apps/clients, critical events and network policies. In authorized test, observe a session before and after a supported event such as account disable, then inspect subsequent resource challenge or denial. Do not simulate against live employees.","Verify resource and client support, sign-in/token behavior and timing. If an unsupported app keeps an existing session, use approved service-specific actions. CAE is not a universal revocation switch.","Why might an existing session survive an account change temporarily?","Unsupported CAE paths or token/session behavior may differ.","CAE removes all policies.","Every token ignores issuer."],[1,null,"Authentication context is a label an integrated app can request for a sensitive operation. A CA policy targets that context and specifies required proof. The app must request the context and validate the result; naming a context alone does nothing to an arbitrary button.","Define c1=PayrollExport, configure approved policy targeting c1 with strength, and have supported app request the required claims/context on export. Normal browse stays under baseline policy. Test export with and without acceptable proof.","Check app integration, context ID and sign-in policy result; inspect relevant token claim and app-side enforcement. Never infer sensitive action is protected solely because context exists.","An export succeeds without strong proof although context c1 exists. What should be checked?","Whether the app requests and validates c1 and the relevant CA policy applies.","Only the context's friendly name.","The user's Microsoft 365 theme."],[1,null,"Protected actions associate selected supported Entra permissions with authentication context so an administrator must satisfy additional proof to perform a sensitive operation. This does not grant the underlying permission.","Identify supported sensitive permission (for example an eligible policy-management action), create context and approved strength policy, associate action in protected actions settings with appropriate admin authorization, pilot before broader use.","Test an admin who has underlying permission but lacks required proof; test the same approved operation after satisfying context. Verify audit and sign-in results and recovery exclusions. Avoid locking out policy administrators.","Can a user perform a protected admin action merely by satisfying its authentication context?","No; the user must also have the underlying administrative permission.","Yes, context grants Global Admin.","Yes, if they own an app."],[0,13,"Conditional Access templates prepopulate recommended policy settings. They accelerate drafting, not organizational risk assessment; scope, exclusions and controls must be inspected before enabling.","Choose supported template relevant to business goal, review generated name, identities, target resources, exclusions, conditions, grant/session controls and state. Adapt to approved pilot and test report-only, then documented enforcement approval.","Check representative sign-in logs for unexpected impact and recovery path. Templates may change; record resulting actual policy configuration rather than trusting template title.","What should you do after generating a policy from a template?","Inspect all settings, scope and exclusions and validate pilot outcomes.","Enable immediately without review.","Delete every existing policy."],[1,14,"User risk represents likelihood the identity is compromised, aggregated from relevant detections. Risk-based access/remediation can use supported Entra ID Protection and CA, depending on licenses and configuration; user risk differs from a specific sign-in risk.","Review risky user record, detections and history. Design scoped policy for approved remediation or block at selected risk level; for password-based compromised users, use supported secure password-change/recovery conditions as appropriate. Check registration prerequisites.","Confirm risk disposition and actual approved recovery; investigate false positives using evidence. Do not dismiss risk merely to allow a sign-in. Verify new sign-in and monitor related activity.","A user remains high risk after one low-risk sign-in. Is that contradictory?","No; account-level risk and one event's sign-in risk are separate.","Yes, all sign-in events reset user risk.","Yes, risk is a licensing error."],[1,14,"Sign-in risk concerns probability that a specific authentication request is not legitimate. It is evaluated from supported detection signals and can trigger step-up or block depending on policy. It does not necessarily mean account compromise is confirmed.","Inspect risky sign-in details, time, user, resource, client and detection type. Plan pilot risk policy for specified levels, with approved proof/block outcome. Do not generate malicious sign-ins in a real tenant to practice.","Correlate actual event and policy result, confirm legitimate or compromised disposition according to approved investigation. Compare user-risk history separately.","An unfamiliar sign-in triggers risk, but no evidence yet establishes compromise. What is appropriate?","Investigate that event and apply approved risk-based controls.","Dismiss all risk detections.","Grant admin rights for verification."],[2,15,"Registration campaigns encourage or require eligible users to set up supported authentication methods during sign-in flows; method policies determine availability. Registering proof does not itself enforce it for every access request.","Authentication methods > Registration campaign: inspect supported target population, exclusions, method eligibility and snooze behavior. Pilot users lacking required registration, provide recovery/helpdesk process and communication. Use approved tenant settings only.","Check registration details and actual sign-in requirements; compare eligible unregistered user and registered user. If no prompt, inspect targeting, eligibility and existing methods.","A campaign finishes and a user registers Authenticator. What still determines whether MFA is required?","Applicable authentication and access policy.","The campaign name alone.","The user's SMTP alias."],[1,14,"Risk investigation is an evidence workflow: identify alert scope, inspect detections, correlated sign-ins, IP/client/resource and account changes; select approved remediation or confirmed-safe disposition. Risk state is not the same as an incident conclusion.","Fictional event E1 shows high sign-in risk; user U1 also has suspicious consent grant. Compare known baseline, audit changes and affected resources; contain approved access, secure credentials, revoke appropriate sessions, remove malicious grant through authorized incident procedure.","Record evidence, risk disposition, verified recovered access and follow-up monitoring. A reset without investigating app grants or workload persistence may leave other exposure.","Which action best follows a confirmed compromised account?","Approved containment/remediation plus verification of credentials, sessions and relevant grants.","Only rename the user.","Only dismiss the alert."],[0,null,"Workload identity risk concerns nonhuman principals and suspicious activity. A service principal can have credentials, permissions, owners and sign-in logs; a user password reset does not fix a compromised application credential.","Inspect risky workload identity, service principal sign-in evidence, credential additions and consent/audit history. Map app ID, principal ID, credential and permissions; rotate/revoke approved compromised credentials or remove unauthorized grants with service-owner coordination.","Test required workload operation using approved replacement credentials, confirm unauthorized operation denied and monitor further sign-ins. Avoid destroying production dependency without rollback.","A risky service principal is using a newly added secret. Which evidence/remediation is relevant?","Principal credentials and grants, audit/sign-in evidence and approved secret rotation.","Reset an unrelated employee password.","Change SharePoint branding."],[2,null,"Global Secure Access client acquires supported network traffic and forwards it according to assigned traffic profiles. Deployment is not simply enabling a CA policy; device support, client health and forwarding configuration matter.","Plan pilot users/devices, check current client prerequisites and licensing, deploy supported client under approved management, enable required forwarding profile and assignment, verify traffic acquisition and health. Do not purchase GSA licenses for practice.","Inspect client status/diagnostics and traffic logs for intended destinations; distinguish client disconnected, profile not assigned and app authorization denial.","Client is installed but traffic not acquired. What should be checked first?","Client health, forwarding profile, assignment and supported destination.","The user's company logo.","A PIM approval for every packet."],[2,null,"Entra Private Access provides identity-aware access to supported private applications through connectors and app segments. Connector reachability, destination host/port and assigned user/policy are separate requirements.","Design Payroll private host/port, deploy approved connector group with reachability and redundancy, configure supported Quick Access or per-app segment as appropriate, assign pilot users, apply suitable CA policy and client profile.","Validate private DNS/host/port path, connector health and authorized access; test denied unassigned user. If sign-in succeeds but target unreachable, check connector and segment rather than resetting password.","All users authenticate, but connector to private Payroll is down. What fails?","Private application connectivity path.","Tenant branding.","User licensing assignment only."],[2,null,"Entra Internet Access is a secure web gateway capability for supported internet traffic. Forwarding, filtering/security policies and identity-based controls depend on enabled profiles, license and supported client/configuration.","Plan pilot internet traffic forwarding, define approved web/content filtering requirements, assign security profiles/policies as supported and test permitted and blocked categories/destinations. Inspect policies and actual traffic acquisition before rollout.","Review traffic logs and policy enforcement, compare intended internet traffic with private access and Microsoft 365 traffic. No broad production changes or paid activation.","What differs from Private Access?","Internet Access governs supported public internet traffic; Private Access connects authorized users to private apps.","Internet Access changes AD source anchor.","Private Access always replaces DNS."],[2,null,"The Microsoft traffic profile acquires supported Microsoft 365 traffic for GSA capabilities; other profiles govern private/internet traffic. Profile assignment and supported destinations determine acquisition, not a general right to every cloud app.","Select approved Microsoft traffic profile for pilot, configure supported client or remote network as applicable, inspect forwarding targets and test a representative Microsoft 365 request. Review actual workload sign-in/traffic context separately.","Verify traffic acquisition logs and intended CA/network signal where supported. If Teams works but acquisition is absent, check client/profile and supported destination rather than assuming policy enforcement.","Does enabling the Microsoft 365 profile automatically forward every private Payroll server?","No; private application segments and appropriate forwarding configuration are separate.","Yes, all IP traffic is always acquired.","Yes, if the user is a guest."]],[[1,null,"Choose identity by execution environment and credential lifecycle. A user account represents a human and may require interactive proof. A service principal represents an app in a tenant. A managed identity is an Azure-managed principal for supported resources. A managed service account or group managed service account (gMSA) is an AD-managed service identity for supported Windows workloads.","For Azure Function reading Key Vault choose managed identity if supported; for an external service choose app registration with supported federated identity credential or certificate; for a Windows domain service choose gMSA where supported. Avoid shared human credentials. Record issuer, principal, credential custody, hosting and intended data scope.","Verify appropriate identity exists, runtime can authenticate without exposing a secret, and only the expected resource operation succeeds. If hosting changes, reevaluate supported identity options.","A supported Azure VM needs to read Key Vault without storing a secret in code. Which identity best fits?","Managed identity with narrowly scoped resource authorization.","Shared Global Administrator user account.","A Windows gMSA for every Azure service."],[1,16,"A system-assigned managed identity is created with a supported resource and its lifecycle is tied to that resource. A user-assigned managed identity is an independent Azure resource that can be associated with multiple supported workloads. Both have tenant-local service principals.","Authorized Azure portal training design: for VM1 enable System assigned under Identity, then inspect principal ID; alternatively create user-assigned ID payroll-reader, note client ID/principal ID/resource ID and assign only to intended resources. No paid resource is created here.","Confirm principal exists and intended resource association; if a system-assigned identity is disabled and re-enabled, check whether a new principal ID needs new role assignments. A user-assigned identity can persist independently.","A single identity must be independently managed and used by two supported workloads. What fits?","User-assigned managed identity.","Two unrelated employee accounts.","A system-assigned identity shared from a deleted VM."],[1,16,"Creating a user-assigned identity and attaching it are separate operations. An Azure resource association lets the workload request tokens for that identity; attachment alone does not grant access to downstream resources. Control-plane permission to attach an identity differs from data-plane permission to use a target.","In a training design choose VM1 > Identity > User assigned > select payroll-reader. Confirm tenant/subscription and identity resource ID. The deployment actor needs supported assignment permissions; the runtime selects identity by applicable client/resource ID where necessary.","Read back resource Identity settings and principal/client IDs. Test requesting the intended resource token through supported Azure SDK/identity endpoint in an authorized environment. If identity cannot be selected, inspect attachment and runtime selection before changing Key Vault role.","User-assigned identity exists but isn't attached to VM1. What must happen before VM1 can use it?","Associate the identity with the supported workload under approved permissions.","Grant everyone Key Vault Administrator.","Register a human MFA method."],[1,16,"A managed identity obtains an access token for a specific target resource. Azure RBAC role assignment connects principal, role definition and resource scope. Key Vault data-plane actions and management actions are different; vaults may use Azure RBAC or the legacy access-policy model.","For payroll-reader, choose intended vault using Azure RBAC, assign applicable Key Vault Secrets User role at appropriate approved scope, request a token for Key Vault via supported credential SDK and read only approved secret. Do not log the token or secret. A Graph token is unsuitable.","Verify allowed read and denied unrelated write/other vault. If 401, inspect audience/credential; if 403, inspect role assignment scope, propagation, permission model and network restrictions. No live secrets are used in academy.","Token audience is Key Vault and signature is valid, but principal has no vault data permission. Why deny?","The resource must authorize the secret operation; valid identity is insufficient.","All Azure tokens grant all resource access.","A managed identity must use employee password."],[0,20,"Enterprise applications expose tenant-local service principal properties, assignment requirement, user visibility, SSO and provisioning. Tenant-level application/consent settings influence defaults; the app object in its home tenant holds registration details. Some settings are not applicable to every app.","Compare tenant-wide user consent policy with Payroll enterprise app Assignment required=Yes and its specific users/groups. Inspect service principal ID, sign-in enabled state, SSO mode and provisioning state. Use current Entra app screens; label each setting's scope.","Test assigned versus unassigned pilot user and inspect sign-in logs. If app assignment succeeds but API access fails, inspect token permissions/consent separately. Avoid broad tenant changes to fix one app.","Which setting limits a particular enterprise application's sign-in to assigned principals where supported?","Its app-level assignment requirement and actual assignment.","Tenant company logo.","Directory custom domain verification."],[0,1,"Delegated app administration uses appropriate Entra roles or app ownership, with distinct operations and scope. Application Administrator and Cloud Application Administrator have broad documented permissions with differences. Ownership alone is not equivalent to every tenant-wide consent permission.","Inventory requested action (manage one app vs tenant-wide apps vs grant high-impact API consent). Select narrow supported owner/custom/built-in role and applicable scope; document actor U1, target SP1, operation and approval. Prefer time-bound assignment where appropriate.","Test specific app-management action and denial of unrelated tenant action; check audit and effective role assignments. High-privilege consent operations may need a different authorized role than app configuration.","An employee needs to maintain one approved app, not all tenant apps. What should you evaluate first?","Supported app ownership or appropriately scoped least-privilege role.","Global Administrator permanent assignment.","Exchange license."],[2,null,"Application Proxy publishes supported on-prem web applications with an external URL and connector. With Entra preauthentication, users authenticate to Entra before connector traffic reaches internal app; backend SSO and resource authorization may still be needed. This is distinct from Private Access's broader traffic model.","Design external URL https://payroll-example.msappproxy.net (illustrative), internal URL https://payroll.contoso.example, connector group, preauthentication and assignment. Choose supported SSO mechanism such as Kerberos constrained delegation only after checking SPNs and delegated identity design. No real app is exposed.","Validate external authentication, connector reachability and backend authorization separately. A 502/backend connection issue points toward connector/internal URL; an Entra policy denial points to sign-in evidence. Test only authorized users.","An assigned user authenticates successfully to Application Proxy but backend is unreachable. What should be inspected?","Connector health and internal URL/backend connectivity.","User's mailbox license only.","App display name."],[2,null,"SaaS integration usually has three independent paths: authentication (SAML/OIDC), provisioning (SCIM or other supported mechanism) and authorization (app assignments/target permissions). Identity attributes and matching determine how local accounts relate to Entra.","For fictional SaaS1 configure approved SAML metadata/identifier, reply URL, NameID and signing certificate; configure supported provisioning endpoint with approved credential and attribute mappings; assign pilot group. For OIDC use client/redirect settings instead of SAML assertion fields.","Check sign-in and provisioning logs independently; read back target identity and permitted/denied operations. Successful SAML alone does not prove target account exists or access was removed.","User signs in through SAML but SaaS target account is absent. Which operation should be investigated?","Provisioning scope, mapping and target response.","A global DNS MX change.","Entra theme color."],[0,20,"App assignment connects a principal to an enterprise application's supported role. App roles are values exposed by application definition; user/group assignment determines who gets applicable role claims. Classification organizes users/groups and business roles, not automatic authorization.","Payroll API exposes Reader and Approver roles. Assign Finance Readers group to Reader and approved managers to Approver where supported; set assignment required if appropriate. Inspect role value, allowedMemberTypes, principal object IDs and assignment state. Group licensing is unrelated.","Test a permitted read, denied approve for Reader and authorized approve for manager. Check token role claims and actual resource enforcement. If an app ignores roles, assignment alone cannot enforce its internal operation.","A Reader receives a token containing Reader role but the app permits approval anyway. What is missing?","App-side authorization enforcing the role for that operation.","A second tenant name.","More MFA prompts alone."],[0,21,"Delegated consent grants an app permissions to act with a signed-in user under relevant user rights; application permissions support app-only operations and require appropriate admin consent. Consent policy, admin consent workflow and actual grants are distinct from requested API permissions.","For Payroll Web request only delegated User.Read for profile reading; inspect API permissions and Enterprise applications > Permissions. Review publisher, requested scopes and business need. Use authorized admin approval only if required; reject Directory.ReadWrite.All for a read-only job. Never grant live consent for practice.","Check actual OAuth2 permission grant/app role assignment and token claims; validate intended API call and denied unrelated action. Removing requested permission from registration may not revoke previously granted consent; inspect actual grants.","An app requests broad directory write but only needs current user's profile. Which decision fits least privilege?","Grant only the supported necessary delegated scope after review.","Approve all requested permissions because app is registered.","Grant every user Application Administrator."],[0,null,"My Apps collections organize supported enterprise applications for user discoverability; collection membership/visibility is separate from app assignments, SSO and resource authorization. Users may still be able to reach authorized apps through other links.","In Entra enterprise applications > My Apps collections (navigation may vary), design Finance Tools collection, add approved visible apps and assign appropriate users/groups. Inspect existing app assignments and hidden/visible settings independently.","Sign in as pilot user, confirm collection appearance and actual app access; verify unassigned user cannot gain access merely by seeing link. If missing, inspect collection membership and app visibility/assignment.","Adding Payroll to a My Apps collection grants what by itself?","A supported organization/discoverability arrangement, not resource permission.","Global Admin.","Automatic Graph write scope."],[0,19,"App registration planning chooses supported account types, platform, redirect URIs, token flows, credential model and minimal API permission. A redirect URI must exactly match supported registered callback rules. Public clients cannot safely store confidential secrets.","Design Payroll Web as single-tenant confidential web app with HTTPS registered callback, server-side credential or supported federated identity; for SPA use supported authorization code with PKCE and no client secret. Identify Graph/API audiences and scopes, owners and credential expiry.","Review architecture and current platform docs. Validate exact redirect, tenant/issuer, supported flow and API result in isolated authorized lab; test denied wrong audience. Do not publish real secrets.","Which design avoids storing a confidential client secret in browser code?","SPA/public client using supported authorization code with PKCE.","Client secret embedded in JavaScript.","Global Administrator password in localStorage."],[0,19,"Creating an app registration creates an application definition in its home tenant; a tenant-local service principal represents it for access. Application/client ID, directory/tenant ID and object IDs serve different purposes.","In approved test tenant go App registrations > New registration, select supported account type, name Payroll Web and configured redirect platform if needed; record client ID APP1 and application object ID OBJ1, then inspect Enterprise applications for local service principal SP1. No real registration is made here.","Read back account type, redirect URI and owners; compare IDs before configuring token flow. If request uses local object ID as client ID it can fail app resolution; check tenant and app registration.","Which identifier belongs in OAuth client_id?","Application (client) ID.","Service principal object ID.","User SID."],[3,19,"Application authentication is proof by the client when required, distinct from authenticating the end user. Confidential clients may use certificates, supported client secrets or federated credentials; public clients use supported PKCE and no confidential secret. Redirect/platform settings affect flow.","Configure exact authorized HTTPS callback for web app, select appropriate credential model and expiration, restrict owners and use secure storage. For SPA use supported public-client code flow and PKCE. In fictional token lab compare ID vs access token and wrong audience; do not create real credentials.","Inspect token endpoint error, registered redirect URI, tenant/client ID and credential validity. A mismatched redirect is not repaired by broader API permission. Rotate expiring credentials under approved process and verify workload recovery.","OAuth error says reply URL does not match registration. What should be corrected?","Exact registered redirect URI and requested callback under supported platform rules.","Every user password.","Application API permissions to Directory.ReadWrite.All."],[0,21,"API permission is a defined access capability exposed by resource. Delegated scopes appear in appropriate scp claims for user-context tokens; application permissions are resource app roles used by app-only tokens, commonly represented by roles. Requested, granted and effective permission differ.","For Graph profile read select delegated User.Read; for approved app-only directory inventory select narrow supported application permission only if justified. Inspect app registration requested permissions, actual grants and consent. Call correct resource API with appropriate audience and actor.","Check API result, token scope/role and resource enforcement. A 403 after valid token requires investigating actual grant, role or resource conditions. A token for Payroll does not grant Graph access.","A client credentials flow needs a user-independent permission. Which type is appropriate?","Approved application permission for that resource.","Only delegated scope without user.","A user group display name."],[0,20,"App roles define business permissions in an application: display name, stable value, description and allowed member types (users/groups or applications as supported). Assignment creates a relationship to resource service principal; token role claims must be enforced by application.","Define role Payroll.Read with value Payroll.Read and supported Users/Groups; define separate role Payroll.Export for authorized principals. Assign intended group to read role, appropriate approved principal to export. Inspect role ID/value and assignment; avoid default broad access.","Validate relevant roles claim and actual allowed/denied operations. If role claim is missing, inspect assignment, audience and token flow. If app permits action despite wrong role, fix app enforcement.","A token has Payroll.Read but no Payroll.Export. What should a correctly enforcing app do on export?","Deny export absent other authorized entitlement.","Allow export because token exists.","Grant new role automatically."],[0,17,"Cloud discovery analyzes supported network/endpoint logs to identify cloud service usage, associated users/devices and risk indicators. A discovered app is not automatically connected, approved or blocked. Evidence quality depends on traffic visibility and data source.","In Defender for Cloud Apps review Cloud Discovery dashboard, data sources and discovered apps. Example file-sharing service has high traffic, unsanctioned status and risk findings; inspect observed traffic, business owners and catalog risk factors before policy decision.","Confirm source ingestion, time range and service identification. A service missing from report may reflect lack of visibility rather than no use. Validate any approved restrictions through integrated enforcement path.","An app appears in Cloud Discovery. Does this alone mean its API is connected and content is inspected?","No; discovery and API-connected apps are separate.","Yes, every discovered app is automatically blocked.","Yes, discovery grants admin consent."],[1,null,"Connected apps use supported connectors/API authorization to collect or govern data and activities for a service. Connector access, required permissions and health determine coverage; this is distinct from passive discovery and proxy-based session control.","Identify SaaS service and supported connector; review requested API permissions, tenant/data scope and owner approval. In Defender portal connect only in authorized environment, inspect connection status and ingestion. Do not enable paid connectors for practice.","Verify recent activity and connector health, expected resource scope and approved permissions. If data missing, inspect connection/authentication errors and ingestion delay; review least privilege before reauthorizing.","Cloud Discovery reports SaaS usage but no app-specific file activities are visible. What might be needed?","A supported connected app/API integration with approved permissions.","A new UPN for every user.","Delete the Cloud app catalog."],[1,null,"Application-enforced restrictions pass supported session/device context from Entra to the workload, which applies its own configured limits. A compliant device requirement can deny access; app-enforced restriction can permit limited web actions depending on resource support.","For supported SharePoint unmanaged-device scenario choose approved limited web access, configure corresponding workload control and Conditional Access session setting. Compare managed full access with unmanaged browser limited access; check guest/client behavior per current documentation.","Inspect device context, CA session result and actual workload behavior. If download unexpectedly succeeds, confirm workload-specific settings and supported client/session; do not assume CA app control and application-enforced restrictions are identical.","Unmanaged browser may view a protected site but cannot download. Which design can support that behavior?","Supported workload application-enforced restrictions plus appropriate CA/session configuration.","A domain TXT verification record.","Assign Global Admin to the browser."],[1,18,"Conditional Access App Control routes supported sessions through Defender for Cloud Apps session control capabilities. It requires compatible application onboarding, access policy and client/session behavior. Proxy session evaluation is separate from app-side authorization.","In approved lab onboard supported app, scope CA session control to pilot and choose appropriate monitor/block/download control. In Defender configure session policy for intended action, label/context where supported, and test only controlled data.","Verify sign-in session control applied, relevant session appears in Defender, and allowed action/blocked action observed. If session bypasses control, inspect app/client support, routing, policy targeting and sign-in result.","CA policy names a session control but no Defender session appears. What evidence is needed?","Supported app/client onboarding, session routing and actual CA result.","Mailbox quota only.","PHS sync history only."],[1,18,"Defender for Cloud Apps access policies govern supported access conditions; session policies inspect/control supported in-session activities. These policies act in their applicable enforcement channel, not every arbitrary application request.","Define policy for pilot SaaS: allow authorized login, block download of classified file in unmanaged browser. Choose supported app, users, device context and activity filters; set monitor or enforce as approved and test representative business scenario.","Inspect policy match, alert/event details and real allowed/denied action. If a file action is not detected, verify session routing, policy filters and capability. Avoid universal guarantees across apps.","Which policy type is aimed at an in-session file download action in a supported proxied app?","A relevant session policy.","Only company branding.","A domain-controller replication setting."],[1,null,"OAuth app policies and app governance capabilities can detect or manage suspicious consented apps and permissions under supported licensing/features. Grant inventory includes principal, permission type, resource, consent and activity. High permission alone is not definitive compromise but warrants review.","Inspect fictional app Marketing Export with broad Graph write permissions and unexpected activity. Review publisher, actual consent grants, credential additions, affected resources and business owner. Use approved policy/alert and remediation workflow for excessive or unauthorized grants.","Revoke only approved unauthorized grants/credentials, validate required operations and monitor subsequent sign-ins. Do not revoke all tenant apps indiscriminately. Distinguish app role assignment from OAuth permission grant.","A suspicious app obtained new broad application permissions. What should the investigation inspect?","Actual consent/app-role grants, principal activity, credentials and audit evidence.","Only user profile photos.","Only DHCP lease duration."],[0,17,"The Cloud app catalog provides information and risk factors for recognized cloud services. Sanctioned/unsanctioned classification expresses governance decision; enforcement depends on supported integrations/configuration. Catalog information informs but does not replace business risk assessment.","Review fictional FileShareX risk factors (security, compliance, business need), owner, discovered usage and data sensitivity. Decide sanctioned, unsanctioned or review under approved process; document rationale and intended enforcement mechanism.","Verify tag/status and actual allowed/blocked traffic via configured supported integration. If tagged unsanctioned but traffic still allowed, investigate enforcement path rather than assuming tag is automatic block.","A cloud app is tagged unsanctioned. Does that guarantee all devices block it immediately?","No; supported enforcement integration and policy must actually apply.","Yes, catalog tags are firewalls.","Yes, tags revoke every token."]],[[0,22,"Entitlement management models business access as governed resource roles, request eligibility, approval, expiration and review. An access package is a collection of resource roles; it does not by itself grant access until an assignment exists.","Design Project Alpha for external contractors: project group Member, SaaS Reader, no Finance roles; requester connected partner, sponsor approval, 30-day expiry and review. Identify catalog owner, resource owners and alternate access paths before creation.","Validate required project access, denied Finance access, expiry behavior and removal of package-granted roles. Check direct/inherited grants separately. Use actual authorized tenant for licensing-dependent operations.","Which is the first step in entitlement design?","Define business resource roles, eligible requesters, approval, expiry and verification.","Grant everyone an indefinite Global Admin role.","Create a package name without resources."],[0,22,"A catalog organizes resources and access packages for entitlement management. Resource owners authorize inclusion and catalog roles govern who can manage resources/packages. Catalog availability to external users and package policies are separate controls.","Create training catalog Project Alpha; add approved security group and enterprise application resource roles; assign appropriately scoped catalog owner or access package manager under supported permissions. Decide whether catalog supports external requesters.","Inspect resource list, role options and delegated catalog roles. If resource unavailable to package, check catalog inclusion and owner authorization; external eligibility still requires correct package policy.","A resource exists in Entra but cannot be selected for a package. Which configuration is relevant?","Whether authorized resource and role are included in the catalog.","The user's password age.","The device's PRT."],[0,22,"An access package defines resource roles and one or more assignment policies. The policy determines who can request, whether approval is needed, duration, review and assignment lifecycle. Assignment creates the actual governed entitlement.","Create Project Alpha package in its catalog, select Project Alpha group Member and SaaS Reader, configure partner requester eligibility, sponsor approval, expiry after 30 days and review. Avoid selecting broader Finance roles. Simulate requester and approver separately.","Inspect resulting assignment state and downstream group/app membership; test permitted project and denied Finance. Expiry should remove package-granted resource roles, not necessarily every alternate grant.","The package exists with roles but no assignment. Is requester automatically entitled?","No; an approved/direct eligible assignment under policy must be created.","Yes, package name grants resource access.","Only if the device is hybrid joined."],[0,22,"Access requests follow configured policy from submitted request to approval/denial, assignment delivery and expiration. Request status and assignment status can differ; approved request may encounter delivery errors.","As fictional Casey, request Project Alpha in My Access, enter business justification and requested dates; sponsor approves or denies per policy; inspect requests and assignments. If approved, verify delivery of resource roles rather than only approval status.","Compare request ID, decision, assignment state and resource membership. For failed delivery, inspect resource configuration or provisioning evidence. Test denial for requester outside eligibility.","A request is approved but user still cannot access project resource. What is next?","Check assignment delivery, actual resource roles and access policy.","Approve every unrelated request.","Assume all approval states guarantee resource access."],[0,23,"Terms of use (ToU) is an acceptance requirement that can be targeted with supported Conditional Access. Document version, language, consent record and reacceptance behavior are distinct from the app entitlement. A legal/policy owner must approve text.","Prepare authorized policy document for external contractors, configure appropriate localized document and acceptance options, scope supported CA policy to project access with approved exclusions, pilot acceptance and refusal. Do not publish unapproved legal content.","Review acceptance reporting, user/time/version and actual access outcome. Verify nonacceptance is denied where policy applies. ToU accepted does not authorize unrelated resources.","A contractor accepted terms. Does acceptance grant Project Alpha automatically?","No; resource assignment and other applicable access controls are still required.","Yes, ToU is a directory role.","Yes, acceptance synchronizes AD."],[2,24,"Entitlement external-user lifecycle settings determine supported handling when an external user loses their last access package assignment, including applicable block/removal timelines. Other direct access, business relationships and retention obligations must be reviewed.","Design contractor end-of-contract process: check all package assignments, alternate grants and sponsor; configure approved guest lifecycle behavior in identity governance settings; remove obsolete target access and schedule account handling according to policy. Avoid deleting needed retained data.","Verify actual project denial, package assignment removal, guest state and applicable lifecycle timing; check exceptions for existing other access. An expired package may not prove entire guest relationship has ended.","Why not delete every guest immediately when one package expires?","They may have other approved assignments or retention/lifecycle requirements.","Guest accounts cannot expire.","A guest is always an administrator."],[0,null,"Connected organizations represent approved external organizations in entitlement management and can include supported identity sources and sponsors. Package policy can target connected organization requesters. The configuration does not itself create broad trust or resource access.","Create training PartnerCo connection using appropriate verified identity source/domain; designate approved internal/external sponsors and connected organization status. Scope Project Alpha policy to PartnerCo requesters and sponsor approval.","Test eligible partner requester and unapproved organization requester; inspect organization resolution and request policy. Verify cross-tenant access and actual resource entitlement separately.","Connected PartnerCo is configured. Does every partner employee gain Project Alpha access?","No; package requester eligibility, approval, assignment and access policy still apply.","Yes, connection grants all resources.","Yes, if a sponsor exists."],[0,25,"An access review evaluates whether existing group/app/package/privileged access should continue. Design requires review scope, reviewers, recurrence, duration, default decision, outcome application and exceptions. A review recommendation is not automatic permission enforcement.","For Project Alpha monthly review choose relevant group or package assignments, sponsor or resource owner reviewers, due date and justified no-response/default behavior. Decide whether auto-apply is supported and approved; document escalation and emergency access exclusions.","Verify review population matches intended entitlements; test review completion and applied denied grant. Check reviewer independence and stale ownership. A recommendation without applied decision does not remove access.","What should be decided before creating a recurring contractor access review?","Scope, reviewers, frequency, default behavior and how outcomes will be applied.","Only group display name.","Only tenant background color."],[0,25,"Creating a review instantiates a review definition for selected access, reviewer(s), schedule and settings. Review instance decisions apply to a particular period; recurring definition may create new instances. Supported review sources/licensing differ.","In approved governance access reviews choose group or app/package as applicable, select fictional Project Alpha group, sponsor reviewer, monthly recurrence, seven-day duration and approved completion settings. Preview included access and notification behavior.","Inspect review ID/instance, reviewer assignments and actual population. Verify a denied decision affects intended grant after approved apply. If a user missing, check review scope and membership.","Review created for wrong group. What is the appropriate correction?","Correct approved review scope and verify intended population before applying outcomes.","Approve every review item anyway.","Change the user's UPN."],[0,25,"Monitoring reviews means tracking instances, status, progress, decision types, reviewer response and applied outcomes. Pending decisions may require escalation; completed review may still need outcome application.","Review fictional monthly instance: 10 users, 7 approved, 1 denied, 2 not reviewed. Check due time, reviewer, reason and no-response behavior. Decide approved escalation or completion process; inspect audit history and actual group state.","After completion inspect applied results and target access, not just completion count. If denial didn't remove access, check apply setting, delivery errors or alternate grants.","A review status is Completed but denied user's direct app assignment remains. What is needed?","Inspect applied decision and all alternate resource grants.","Mark incident closed automatically.","Reset every reviewer's password."],[0,25,"Manual review decisions let an authorized reviewer approve or deny continued access and optionally record justification under configured settings. A reviewer should use business evidence, not blindly follow recommendations. Applying results is a separate controlled step.","In fictional review Casey's contract ended. Review membership history, sponsor confirmation and project need; select deny with reason, submit; confirm review application policy and authorized completion. Retain approved exception only with documentation.","Check decision actor/date/reason and applied grant state. Test actual project denial and inspect alternate direct access. If no review authority, do not use another person's account.","A review recommendation says deny, but sponsor provides valid continued need. What should reviewer do?","Make an evidence-based authorized decision with justification according to policy.","Automatically deny regardless of evidence.","Grant Global Admin to bypass review."],[1,26,"PIM distinguishes eligible and active Entra role assignments. Settings can specify activation duration, proof, justification, ticket or approval requirements. Eligibility does not confer active permission; permanent active privileges may remain through other roles.","Choose fictional Conditional Access Administrator eligible assignment to Alex, scope supported role, require approved MFA/strength and justification/approval as configured, max duration one hour for scenario. Use My roles to request activation and inspect active state. Never use actual privileged tenant for unapproved practice.","Test approved role operation before activation (deny), during active window (allow) and after expiry (deny absent other grants). Review audit; if still allowed, inspect alternate active roles and resource/session behavior.","Alex is eligible but has not activated the role. What does eligibility alone confer?","Ability to request activation under policy, not active authority.","Permanent Global Administrator.","Automatic application permission."],[1,11,"Azure resource PIM governs eligible or time-bound Azure RBAC role assignments at supported resource scope. Azure role definitions/scopes differ from Entra directory roles. A subscription/resource assignment does not automatically grant Key Vault data access unless role includes relevant data actions.","In approved Azure environment onboard supported resource scope, select narrowly appropriate resource role, eligible principal and activation settings; compare subscription, resource group and individual resource scopes. Model temporary Key Vault Secrets User for intended vault.","Verify activation and effective Azure RBAC role, allowed approved operation and denied outside scope; after expiry, retest. Inspect activity/PIM history and other assignments. No resources or licenses purchased.","Which scope should a temporary secret reader normally receive when only one vault is needed?","Appropriate data-plane role at narrow supported vault/secret scope, per approved design.","Tenant-wide Global Administrator.","Owner on every subscription."],[1,26,"PIM for Groups supports eligible membership or ownership for applicable groups, with activation controls and time-bound access. Group membership may grant app/resource rights; ownership may permit group management. It is not the same as directory role eligibility unless the group is configured for that purpose.","Choose supported Project Admins group, configure eligible member assignment for approved operator, activation duration and proof/approval requirements. Separately review eligible owner assignment and downstream group-derived permissions. Do not conflate group ownership with app role.","Verify actual membership while active, downstream access, expiration and denied operation; consider propagation and other access paths. Inspect group/PIM audit history.","An eligible group member has not activated membership. What is not yet established by eligibility alone?","Current group membership-derived resource permission.","Existence of eligible assignment.","Potential to request activation."],[1,26,"A PIM request transitions eligible role/group access toward active assignment after configured checks and approval. Approvers review justification and intended scope; approval is not equivalent to granting permanent access. Request, approval and active assignment records are distinct.","Fictional operator requests one-hour Conditional Access role with change-ticket justification. Approver validates business need and requester, approves or denies; inspect activation status and exact expiry. Test denied request and expired role.","Verify only approved activation creates active privilege; check actor, approval time, duration and audit. If pending, inspect approver assignment or policy conditions instead of adding permanent role.","Activation requires approval and request is pending. Should the operator already have the requested active role?","No, unless another assignment independently grants it.","Yes, pending equals active.","Yes, if the role is named in ticket."],[1,26,"PIM audit history tracks assignment and activation-related operations, actors, target roles/groups/resources and timestamps. Reports expose evidence about privilege usage; review sign-in and resource action logs as separate sources.","Investigate Alex activation at 09:05, approval by Casey, expires 10:05, admin change at 09:20. Correlate PIM event, directory audit and relevant sign-in. Check correct principal, scope and actual action, not just display name.","Verify role no longer active after expiry and assess other active roles. Record incident chronology. A PIM activation event alone does not prove which resource changes were performed.","Which evidence shows what administrator actually changed after PIM activation?","Relevant directory/resource audit events correlated with PIM activation history.","Only the activation button label.","Only user MFA registration."],[1,null,"Emergency access accounts provide an independently protected recovery path during identity/policy outages. Microsoft's current guidance recommends multiple cloud-only emergency accounts, strong independently resilient authentication, monitoring and periodic approved validation. They are not daily admin accounts.","Design at least two appropriate cloud-only emergency accounts with approved roles, resilient proof independent of ordinary dependencies, carefully justified CA/recovery configuration and secure credential custody. Set alerts for use and document recovery tests; do not change your real tenant.","Verify approved recovery procedure works during modeled federation/CA outage and alerts trigger; monitor any use, protect credentials and avoid ordinary use. Never exclude broad user groups as emergency access.","Why should recovery accounts not all depend on the same on-prem federation service?","A single dependency failure could block all recovery.","Federation always grants emergency roles.","All cloud accounts require on-prem DNS."],[0,27,"Sign-in logs report authentication and applicable policy events; audit logs record supported directory changes; provisioning logs report source/target provisioning actions. Correlation ID, timestamp, user/principal, resource and tenant context identify a relevant event, but not all logs share the same IDs.","Fictional sign-in 10:05 Alex to Payroll result 53003; audit 09:00 Casey group update; provisioning 10:04 Alex target created. Read Sign-in logs > authentication/Conditional Access/device details first for current failure; inspect audit for configuration change and provisioning for account sync.","Identify first failing boundary and retain relevant event IDs. Validate original operation after approved correction; don't infer cause from unrelated recent audit event. Access/retention depend on role and license.","Which logs best explain why a particular cloud sign-in was blocked by CA?","Actual sign-in event and its policy/authentication/device details.","Only provisioning log.","Only billing report."],[0,27,"Diagnostic settings route selected log categories from Entra to supported destinations such as Log Analytics workspace, storage account or Event Hubs. Workspaces support analysis; storage supports archival; event hubs support streaming to consumers. Permissions, retention and ingestion/storage costs differ.","Plan desired categories (sign-in, audit, provisioning where supported), destination resource ID, region/retention/access needs and estimated cost. In authorized Azure portal/Entra monitoring create only approved diagnostic setting. Here draw source → category → destination → authorized query/consumer; no resources enabled.","Verify selected category arrives with expected time range and schema; inspect permissions/ingestion delays and retention. Never assume telemetry export is free; confirm cost and data handling before real activation.","What must be decided before enabling diagnostic export?","Destination, categories, permissions, retention and cost impact.","Only tenant logo.","Only group license."],[1,27,"Kusto Query Language (KQL) queries structured tables through pipe-delimited operators. where filters rows, project selects columns, summarize aggregates. Query semantics depend on actual Log Analytics schema, and result counts count events unless explicitly distinct.","Use fictional SigninLogs | where ResultType != '0' | project UserPrincipalName, AppDisplayName, ResultType. Then summarize Count=count() by UserPrincipalName after filtering. In real authorized workspace verify table/column existence and time range; schema and event categories may differ.","Compare fixture row counts before/after filters and aggregates. A successful query against wrong time window or table does not prove absence of incidents. Do not deploy a workspace for practice.","To count failed sign-in events per user, which operation order is appropriate?","Filter failed rows with where, then summarize count() by user.","Project tenant logo then count licenses.","Summarize all events and assume every event failed."],[0,27,"Workbooks visualize supported query data and parameters such as time range, filters and grouped results. Reports show summarized identity activity; underlying data source, permissions and query determine meaning. A chart is not proof of causal relationship.","Design failed-sign-in workbook with time selector, user filter and query counting failed events per user/app. Choose table and chart; include total event count and data freshness. Compare SigninLogs and AuditLogs in separate views.","Reconcile visualization with raw query and time range; check missing log categories or ingestion delay. Validate source and metric definition before reporting to leadership.","A workbook shows zero failures. What should you check before declaring all sign-ins healthy?","Data source, ingestion, query filter, time range and permissions.","The chart color alone.","Whether every user has a license."],[2,28,"Identity Secure Score aggregates supported identity security recommendations and progress. Score is a prioritization signal, not certification of security or guarantee of risk elimination. Recommendations may depend on licensing, configuration and assessed state.","Review training recommendations: reduce standing privilege, strengthen proof, review risky identities. For each identify affected population, business impact, required license and approved implementation/rollback. Prioritize highest relevant risk instead of blindly maximizing points.","Validate actual control and allowed/denied behavior; monitor recommendation status after supported assessment refresh. If score changes, inspect underlying recommendation evidence and scope. Do not buy licenses solely to improve a score.","A high Secure Score is reported but an obsolete direct privileged grant remains. What should you do?","Investigate and remediate the actual grant under approved policy; score alone is insufficient.","Ignore because score is high.","Disable all monitoring."]]],directLabNames=["Lab_00_SetUpLabResources","Lab_01_ManageUserRoles","Lab_02_WorkingWithTenantProperties","Lab_03_AssignLicensesToUsersByGroupMembershipAAD","Lab_04_ConfigureExternalCollaborationSettings","Lab_05_AddGuestUsersToTheDirectory","Lab_06_AddFederatedIdentityProvider","Lab_07_AddHybridIdentityWithAzureADConnect","Lab_08_EnableAzureADMultiFactorAuthentication","Lab_09_ConfigureAndDeploySelfServicePasswordReset","Lab_10_AzureADAuthenticationForWindowsAndLinuxVM","Lab_11_AssignAzureResourceRolesInPrivilegedIdentityManagement","Lab_12_ManageAzureADSmartLockoutValues","Lab_13_ImplementAndTestAConditionalAccessPolicy","Lab_14_EnableSignRiskPolicy","Lab_15_ConfigureAAD_MultiFactorAuthRegPolicy","Lab_16_UsingAzureKeyVaultForManagedIdentities","Lab_17_DefenderForCloudAppsDiscoveryAndRestrictions","Lab_18_DefenderForCloudAppsAccessPolicies","Lab_19_RegisterAnApplication","Lab_20_ImplementAccessManagementForApps","Lab_21_GrantTenantWideAdminConsentToAnApplication","Lab_22_CreateAndManageACatalogOfResourcesInAADEntitlementManagement","Lab_23_AddTermsOfUseAcceptanceReporting","Lab_24_ManageTheLifecycleOfExternalUsersInAADIdentityGovernanceSettings%20","Lab_25_CreatingAccessReviewsForUsers","Lab_26_ConfigurePrivilegedIdentityManagementForAADRoles","Lab_27_MicrosoftSentinelKustoQueries","Lab_28_MonitorIdentitySecureScore"];
const directLab=n=>msLabIndex+'Instructions/Labs/'+directLabNames[n]+'.html';
const depthRows=msDomains.flatMap((d,i)=>d[2].map((a,j)=>{const x=depthData[i][j],shift=(i+j)%3,opts=[x[6],x[7],x[8]];return {id:'D'+(i+1)+'.'+(j+1),chapter:a[0],title:a[1],unit:x[0],lab:x[1],mechanism:x[2],configuration:x[3],verification:x[4],question:x[5],options:[...opts.slice(shift),...opts.slice(0,shift)],answer:(3-shift)%3,correctText:x[6],route:a[3]};}));
s.ms.depth=s.ms.depth&&typeof s.ms.depth==='object'?s.ms.depth:{};
const depthGet=id=>depthRows.find(r=>r.id===id);
const depthState=id=>s.ms.depth[id]||{attempts:0,first:null,last:null,note:''};
const depthCount=ch=>{const rows=ch?depthRows.filter(r=>r.chapter===ch):depthRows;return {total:rows.length,correct:rows.filter(r=>depthState(r.id).last===r.answer).length,firstCorrect:rows.filter(r=>depthState(r.id).first===r.answer).length,notes:rows.filter(r=>String(depthState(r.id).note||'').trim()).length};};
function depthCard(r,open=false){const a=depthState(r.id),attempted=Number.isInteger(a.last);const result=attempted?'<div class="un-result"><b>'+H(a.last===r.answer?'Correct — keep explaining the reason':'Not yet — review the mechanism')+'</b>'+P('Correct reasoning: '+r.correctText)+P(r.verification)+P('First attempt: '+(a.first===r.answer?'correct':'needs review')+' · '+a.attempts+' attempt(s)')+'</div>':'';
return '<details class="un-detail un-objective" id="objective-'+H(r.id.replace('.','-'))+'" '+(open?'open':'')+'><summary>'+H(r.id+' · '+r.title)+(a.last===r.answer?' · ✓':'')+'</summary><div class="un-detail-body"><div class="un-kicker">SC-300 skill lesson · '+H(r.id)+'</div><h3>What it is, how it works, and why it matters</h3>'+P(r.mechanism)+'<h3>Concrete configuration · follow the fields and decisions</h3>'+P(r.configuration)+'<h3>Verify the result, then troubleshoot</h3>'+P(r.verification)+'<h3>Apply it · scenario check</h3>'+P(r.question)+'<div class="un-choices">'+r.options.map((x,j)=>'<button class="btn '+(a.last===j?'primary':'')+'" data-action="ms-depth-answer" data-id="'+H(r.id)+'" data-value="'+j+'">'+H(x)+'</button>').join('')+'</div>'+result+'<form class="un-depth-notes" data-id="'+H(r.id)+'"><label><b>Practice evidence / your own explanation (optional)</b><textarea name="note" aria-label="Practice evidence">'+H(a.note||'')+'</textarea></label><button type="submit" class="btn">Save evidence note</button></form>'+(r.route?B(r.route,'Practice related operation in the academy (partial model)'):'')+(r.lab!==null?'<p>'+A(directLab(r.lab),'Microsoft lab '+String(r.lab).padStart(2,'0')+' · full official instructions')+'</p>':'')+'<p>'+A(msGuide,'Microsoft official skill guide')+'</p><p class="small muted">Original teaching explanation. Configuration paths are conceptual or portal landmarks; verify the current Microsoft procedure, licensing and approved test environment before any real changes. The case check and notes do not establish actual tenant competency.</p></div></details>';}
function depthUnit(ch,i){const rows=depthRows.filter(r=>r.chapter===ch[0]&&r.unit===i);if(!rows.length)return '';return '<section class="un-depth"><h3>SC-300 skill-by-skill instruction · '+rows.length+' skills</h3>'+P('Learn these concrete operations now, before moving to the next teaching unit. Each includes mechanism, configuration, verification and an original case check.')+rows.map((r,j)=>depthCard(r,j===0)).join('')+'</section>';}
function depthChapterSummary(ch){const p=depthCount(ch[0]);return p.total?sec('Certification learning progress',P(p.correct+' of '+p.total+' objective checks currently correct · '+p.firstCorrect+' correct on first attempt · '+p.notes+' evidence notes saved.')+P('These checks measure understanding, not completed official labs. For practice results, use the relevant simulator or authorized real tenant.')+depthRows.filter(r=>r.chapter===ch[0]).map(r=>'<div class="un-word">'+H(r.id+' · '+r.title)+' '+(depthState(r.id).last===r.answer?'✓':'')+' <button class="btn" data-action="ms-depth-open" data-id="'+H(r.id)+'">Return to lesson</button></div>').join('')):'';}
function depthAudit(){const checks=[],check=(name,pass)=>checks.push({name,pass:!!pass});check('All 98 objective lessons independently authored and mapped',depthRows.length===98&&new Set(depthRows.map(r=>r.id)).size===98);check('Every source objective has a matching lesson',msDomains.every((d,i)=>depthData[i].length===d[2].length));check('All 29 direct lab links unique and valid path format',directLabNames.length===29&&new Set(directLabNames).size===29&&directLabNames.every((v,i)=>directLab(i).startsWith(msLabIndex+'Instructions/Labs/Lab_')));
for(const r of depthRows){check(r.id+' teaching schema and placement',!!teachingUnits[r.chapter]?.[r.unit]&&r.mechanism.length>=100&&r.configuration.length>=100&&r.verification.length>=80&&r.question.length>15&&r.options.length===3&&new Set(r.options).size===3&&r.options[r.answer]===r.correctText&&(r.lab===null||directLabNames[r.lab]));const html=depthCard(r);check(r.id+' full content rendered',html.includes(H(r.mechanism))&&html.includes(H(r.configuration))&&html.includes(H(r.verification))&&html.includes(H(r.question))&&html.includes('ms-depth-answer')&&html.includes('un-depth-notes'));}
for(const ch of curriculum){let page=chapterPage(ch);check(ch[0]+' correct embedded objective count',(page.match(/class="un-detail un-objective"/g)||[]).length===depthRows.filter(r=>r.chapter===ch[0]).length);}
return checks;}

function chapterPage(c){const i=curriculum.indexOf(c),st=status(c),words=vocab(c),qs=qset(c);return layout(B('course/home','← Course home')+'<div class="un-kicker">Chapter '+(i+1)+' of '+curriculum.length+' · '+H(c[2])+'</div><h1>'+H(c[1])+'</h1>'+P(c[3])+sec('Prerequisite and progression',P(i?'First understand '+curriculum[i-1][1]+'.':'No prior technical experience required.')+P('Stages here: '+teachingStages.filter(z=>z[0]===c[0]).map(z=>z[3]).join(' → ')))+sec('Business situation',P(c[4]))+'<h2>1–3 · Vocabulary, Understand the whole system, and Technical depth</h2>'+P('Learn one idea at a time. Each lesson introduces vocabulary when you need it, explains the mechanism, follows a concrete example, and asks you to predict the outcome before revealing the answer.')+orderedTeaching(c)+'<h2>4 · Apply what you learned</h2>'+sec('Concrete practice assignment',P(c[11][0])+P(c[11][1])+c[13].map(r=>B(r,labels[r]||r)).join('')+P('Use fictional data only unless you have explicit permission for a real lab. The academy does not provision Azure or Microsoft 365 resources.'))+msSection(c)+'<h2>5 · Check understanding</h2>'+P(st.correct+' of '+st.total+' current answers correct. These are learning checks with feedback, not an independent exam.')+qs.map((q,n)=>question(c,q,n)).join('')+'<h2>6 · Teach it back and prove it</h2>'+sec('Write your own explanation','<p>Explain the exact components, their inputs and outputs, what changes state, what fails and how you verify the result. A saved explanation is self-reported evidence, not automatically graded mastery.</p><form id="un-notes" data-id="'+H(c[0])+'"><textarea name="notes" aria-label="Your chapter explanation">'+H(s.notes[c[0]]||'')+'</textarea><button class="btn primary" type="submit">Save explanation</button></form>')+masteryPanel(c)+depthChapterSummary(c)+sec('Continue in order',P(chapterEvidence(c).ready?'Chapter concept checks and checkpoint are correct and your explanation is saved. Verify practical work separately.':'Complete concept checks, checkpoint and teach-back before moving on. You can review ahead, but the course recommends the earliest incomplete chapter.')+(i?B(croute(curriculum[i-1]),'← Previous chapter'):'')+(i<curriculum.length-1?B(croute(curriculum[i+1]),'Next chapter →'):B('course/practice','Independent practice and assessment'))));}
function recall(){const c=chapter(s.chapter)||recommendation(),x=progress();return layout('<h1>Recall and review</h1>'+P('Study the terms at the point you encounter them, then use spaced recall. Prioritize missed checks rather than reading every path again.')+sec('Current chapter: '+c[1],vocab(c).map(vdetail).join('')+B(croute(c),'Return to chapter'))+sec('Targeted revision',curriculum.filter(c=>!status(c).done).map(c=>'<p>'+H(c[1])+' · '+status(c).correct+'/'+status(c).total+' '+B(croute(c),'Review checks')+'</p>').join('')+P(x.done===curriculum.length?'All current concept checks correct; use independent assessment.':'Start with the earliest incomplete chapter.'))+sec('Full recall tools',B('v17/cards','Spaced recall flashcards')+B('v15/vocabulary','Search all identity vocabulary')+B('v15/systems','Visual system reference')));}
function practice(){return layout('<h1>Practice and assessments</h1>'+P('Use these tools after the related chapter. They are exercises inside the same learning journey, not competing courses.')+msPracticeHub()+curriculum.filter(c=>c[13].length).map(c=>sec(c[1],P(c[11][0])+c[13].map(r=>B(r,labels[r]||r)).join(''))).join('')+sec('Official certification preparation','<p>'+A('https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-300','Current official objectives')+' · '+A('https://microsoftlearning.github.io/SC-300-Identity-and-Access-Administrator/','Official practical lab instructions')+'</p>'+B('objectives','Objective tracker')+B('exams','Existing exam bank')+B('v7/advanced-exam','Advanced independent practice')+P('Real labs may require an authorized licensed tenant. No simulation score guarantees exam success.')));}
function evidence(){const x=progress(),engine=window.__V12_TESTS,missions=['joiner','pilot','workload','contractor'];let state=missions.map(id=>{let m=engine?.getMission(id),a=engine?.getAttempt(id);let valid=!!(m&&a?.submitted&&engine.stillValid(m,a));return '<li>'+H(id)+': '+H(valid&&a?.mode==='exam'&&a?.knowledge?'independent modeled criteria currently met':valid?'modeled configuration criteria currently met':'not currently verified')+'</li>';}).join('');let lab=window.__V17_TESTS.state.lab,ok=window.__V17_TESTS.criteria(lab).every(z=>z[1]);return layout('<h1>My learning evidence</h1>'+sec('Concept understanding',P(x.correct+' / '+x.total+' current correct answers; '+x.done+' / '+curriculum.length+' chapters have all checks correct.')+P(masteryCount()+' / '+curriculum.length+' chapters with learning checkpoints complete (not certified mastery).')+curriculum.map(c=>P(c[1]+': '+(chapterEvidence(c).case?'checkpoint correct':'checkpoint pending or needs review')+'; first attempt '+(caseRecord(c).first?caseRecord(c).first.score+'/2':'not attempted')+'; teach-back '+(chapterEvidence(c).explanation?'saved':'not saved'))).join('')+P('Prior learning records are preserved: V16 '+v16.score()+' correct concept answers; V17 '+v17.lessons.filter(l=>v17.state.answers[l[0]]===l[11]).length+' correct lesson checks. These are not automatically credited as new chapter checks.')+chapterList())+sec('Practical evidence (existing state)',P('Hybrid onboarding criteria currently '+(ok?'met':'not met')+'.')+'<ul>'+state+'</ul>'+B('course/practice','Open practical exercises'))+sec('Local reflections',curriculum.filter(c=>s.notes[c[0]]).map(c=>detail(c[1],P(s.notes[c[0]]))).join('')+P('Notes are self-reported and not scored.'))+sec('Backup and certification limits','<button class="btn" data-action="un-export">Export unified learning progress</button>'+B('notes','Existing academy backup and progress')+P('The unified export includes unified chapter answers and reflections plus copies of V16 and V17 local learning state. The existing academy has its own export. This does not certify exam readiness or real tenant competency.')));}
render=()=>{const r=current();if(['home','learn','v14/path','v16/home','v17/home'].includes(r)){location.hash='#/course/home';return render();}if(!r.startsWith('course/')){oldRender();return;}let out;if(r==='course/home')out=intro();else if(r==='course/chapters')out=chapterIndex();else if(r==='course/recall')out=recall();else if(r==='course/practice')out=practice();else if(r==='course/evidence')out=evidence();else if(r==='course/coverage')out=msCoverage();else if(r==='course/assessment')out=msExamPage();else if(r==='course/lab/commands')out=msCommandPage();else if(r.startsWith('course/lab/'))out=msSim(r.split('/').at(-1));else if(r.startsWith('course/chapter/')){let c=chapter(r.split('/').at(-1));if(c){s.chapter=c[0];s.opened[c[0]]=true;persist();out=chapterPage(c);}else out=chapterIndex();}else out=intro();$('root').innerHTML=shell(out,r);document.title='Microsoft Identity Academy · One learning journey';lastRenderedHash=location.hash;};
